import{Elevator,clamp}from './engine.js';
const $=id=>document.getElementById(id),sim=new Elevator();
let running=false,last=0,accumulator=0,view='position',mode='sandbox',level=0,won=false,blood=true,particles=[],stains=[],shake=0,drawTick=0;
const colors={lime:'#7dccff',cyan:'#f6f7ff',purple:'#f18b9e',dim:'#8594ac'};
const lessons=[{title:'01. Tame the bounce.',text:'Start with P only. Add D until the elevator reaches floor 03 with less than 8% overshoot. Keep at least 80% health.',hint:'Hold P around 1.8. Try D between 2 and 4. The balanced cabin does not need I to hold height.',p:1.8,i:0,d:0,n:0,f:3}, {title:'02. Control the memory.',text:'The cabin is balanced. Too much I can still carry it past the target. Tune I, its limit, or zero-crossing reset to settle with at least 80% health.',hint:'No holding force is needed. Start with I = 0 and D = 3.5, then experiment with small I gains.',p:1.8,i:.4,d:3.5,n:2,f:3},{title:'03. The full house.',text:'Deliver six passengers to floor 04. Settle within 25 seconds, below 8% overshoot, with at least 80% health.',hint:'More mass changes the response. Start near P = 1.8, I = 0, D = 4.2. Tune and retry.',p:1.8,i:0,d:1.2,n:6,f:4}];
function setGains(p,i,d){for(const [key,v]of [['kp',p],['ki',i],['kd',d]]){sim[key]=v;$(key).value=v;$(key+'-number').value=v;}}
function updateFloor(){document.querySelectorAll('[data-floor]').forEach(b=>{const on=Number(b.dataset.floor)*3===sim.target;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on);});}
function status(){ $('run').textContent=running?'Ⅱ Pause':'▶ Run elevator';$('run-status').textContent=running?'● RUNNING':sim.t?'PAUSED':'READY';}
function reset(){sim.reset();particles=[];stains=[];shake=0;running=false;accumulator=0;won=false;$('next-lesson').hidden=true;status();$('ride-caption').textContent='A fresh ride. Your gains are unchanged.';}
function changeFloor(f){sim.setTarget(f);updateFloor();$('ride-caption').textContent=`Destination: ${f===0?'ground floor':'floor 0'+f}. Adjust the gains while it moves.`;}
function updateLoad(){ $('pax').value=sim.count;$('mass-label').textContent=sim.cabinMass+' kg ↔ '+sim.counterweightMass+' kg';$('less').disabled=sim.count===0||mode==='challenge';$('more').disabled=sim.count===6||mode==='challenge';}
function setMode(m){mode=m;$('sandbox').classList.toggle('selected',m==='sandbox');$('challenges').classList.toggle('selected',m==='challenge');$('sandbox').setAttribute('aria-pressed',m==='sandbox');$('challenges').setAttribute('aria-pressed',m==='challenge');document.querySelectorAll('[data-floor]').forEach(b=>b.disabled=m==='challenge');$('preset').disabled=m==='challenge';if(m==='challenge'){loadLesson();}else{$('coach-heading').textContent='LEARN BY BREAKING THINGS';$('lesson-label').textContent='YOUR FIRST EXPERIMENT';$('lesson-title').textContent='A little less bounce.';$('lesson-text').textContent='Run the elevator and watch it overshoot. Increase D while it moves. Notice how the cyan braking force calms the ride.';$('challenge-steps').hidden=true;$('next-lesson').hidden=true;reset();updateLoad();}}
function loadLesson(){const l=lessons[level];setGains(l.p,l.i,l.d);sim.setCount(l.n);sim.target=l.f*3;reset();updateFloor();updateLoad();$('preset').value='custom';$('coach-heading').textContent='THE TUNING CHALLENGES';$('lesson-label').textContent=`EXPERIMENT ${level+1} OF 3`;$('lesson-title').textContent=l.title;$('lesson-text').textContent=l.text;$('insight').textContent=l.hint;$('challenge-steps').hidden=false;$('challenge-steps').textContent='○ Reach target   ○ Smooth ride';}
for(const key of ['kp','ki','kd'])for(const id of[key,key+'-number'])$(id).addEventListener('input',()=>{const n=Number($(id).value);if(!Number.isFinite(n))return;const v=clamp(n,0,Number($(key).max));sim[key]=v;$(key).value=v;if(id===key)$(key+'-number').value=v;$('preset').value='custom';sim.dwell=0;sim.settle=null;});
for(const key of ['kp','ki','kd'])$(key+'-number').addEventListener('change',()=>$(key+'-number').value=sim[key]);
$('run').onclick=()=>{running=!running;status();};$('reset').onclick=reset;
document.querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>changeFloor(Number(b.dataset.floor)));
$('more').onclick=()=>{sim.setCount(sim.count+1);updateLoad();};$('less').onclick=()=>{sim.setCount(sim.count-1);updateLoad();};
$('preset').onchange=()=>{const presets={bouncy:[1.8,0,.5],smooth:[1.8,0,3.5],slow:[.8,0,3.4],chaos:[12,4,0]};if(presets[$('preset').value]){setGains(...presets[$('preset').value]);reset();}};
$('integral-limit').addEventListener('input',()=>{if($('integral-limit').value==='')return;sim.setIntegralLimit(Number($('integral-limit').value));});
$('integral-limit').addEventListener('change',()=>{$('integral-limit').value=sim.integralLimit;});
$('zero-integral').onchange=()=>{sim.zeroIntegralOnCrossing=$('zero-integral').checked;};
$('blood').onchange=()=>{blood=$('blood').checked;if(!blood){particles=[];stains=[];}document.querySelector('.blood-label').textContent=blood?'● STYLIZED BLOOD':'BLOOD EFFECTS OFF';};$('clean').onclick=()=>{particles=[];stains=[];};
$('sandbox').onclick=()=>setMode('sandbox');$('challenges').onclick=()=>{level=0;setMode('challenge');};$('next-lesson').onclick=()=>{if(level<2){level++;loadLesson();}else{level=0;setMode('sandbox');}};
$('help').onclick=()=>$('help-dialog').showModal();$('close-help').onclick=$('start-help').onclick=()=>$('help-dialog').close();
function graphTab(v){view=v;$('position-tab').classList.toggle('selected',v==='position');$('force-tab').classList.toggle('selected',v==='forces');$('legend').innerHTML=v==='position'?'<span class="legend-line lime"></span>Position <span class="legend-line target"></span>Target':'<span class="lime">━ P</span> <span class="purple">━ I</span> <span class="cyan">━ D</span> <span>kN</span>';}
$('position-tab').onclick=()=>graphTab('position');$('force-tab').onclick=()=>graphTab('forces');
window.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName)||$('help-dialog').open)return;if(e.code==='Space'){e.preventDefault();$('run').click();}if(e.key.toLowerCase()==='r')reset();if(/^[0-4]$/.test(e.key)&&mode==='sandbox')changeFloor(Number(e.key));});
function canvas(id){const c=$(id),r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(c.width!==Math.round(r.width*d)||c.height!==Math.round(r.height*d)){c.width=Math.round(r.width*d);c.height=Math.round(r.height*d);}const ctx=c.getContext('2d');ctx.setTransform(d,0,0,d,0,0);return{ctx,w:r.width,h:r.height};}
function line(c,x1,y1,x2,y2,color,width=1){c.strokeStyle=color;c.lineWidth=width;c.beginPath();c.moveTo(x1,y1);c.lineTo(x2,y2);c.stroke();}
function rect(c,x,y,w,h,fill){c.fillStyle=fill;c.fillRect(x,y,w,h);}
function circle(c,x,y,r,color){c.fillStyle=color;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();}
function text(c,s,x,y,color='#8697b1',size=11){c.fillStyle=color;c.font=`${size}px ui-monospace,monospace`;c.fillText(s,x,y);}
function emit(severity){if(!blood||!sim.count)return;shake=Math.min(6,severity);for(let n=0;n<Math.min(50,Math.round(severity*8));n++){const x=.2+Math.random()*.6,y=.25+Math.random()*.45;particles.push({x,y,vx:(Math.random()-.5)*3,vy:-Math.random()*3,life:.6+Math.random(),r:1+Math.random()*2});}if(particles.length>450)particles.splice(0,particles.length-450);for(let n=0;n<Math.min(12,severity*2);n++)stains.push({x:Math.random(),y:Math.random(),r:1+Math.random()*4,drip:Math.random()*14});if(stains.length>180)stains.splice(0,stains.length-180);}
function animateBlood(dt){for(const p of particles){p.vy+=4*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.x<0||p.x>1||p.y>1||p.y<0){stains.push({x:clamp(p.x,0,1),y:clamp(p.y,0,1),r:p.r,drip:Math.random()*12});p.life=0;}}particles=particles.filter(p=>p.life>0);if(stains.length>180)stains.splice(0,stains.length-180);shake*=Math.exp(-12*dt);}
function drawShaft(){const{ctx:c,w,h}=canvas('shaft');c.clearRect(0,0,w,h);const cx=w*.46,scale=(h-115)/15,bottom=h-43,cw=Math.min(160,w*.33),ch=2.5*scale,x=cx-cw/2,y=bottom-sim.y*scale-ch;
 // Functional cross-section: guide rails, floor heights, cabin and counterweight.
 rect(c,cx-cw/2-24,43,cw+48,h-75,'#090e19');for(let z=45;z<h-30;z+=22)line(c,cx-cw/2-24,z,cx+cw/2+24,z,'#121d30');
 for(const side of[-1,1]){const rx=cx+side*(cw/2+15);rect(c,rx-2,44,4,h-78,'#293b55');line(c,rx+2,44,rx+2,h-34,'#506582');for(let yy=60;yy<h-30;yy+=43){rect(c,rx-6,yy,12,3,'#30435e');}}
 for(let f=0;f<5;f++){const yy=bottom-f*3*scale;const on=sim.target===f*3;c.setLineDash(on?[5,5]:[]);line(c,24,yy,w-86,yy,on?'#739bc2':'#29354c');c.setLineDash([]);text(c,f===0?'G':'0'+f,24,yy-9,on?colors.lime:'#8697b1',14);text(c,(f*3).toFixed(0)+' m',54,yy-9,'#64799a',10);if(on){text(c,'TARGET',w-155,yy-8,colors.lime,9);}}
 for(let n=-1;n<=1;n++)line(c,cx+n*7,44,cx+n*7,y,'#7388a6');circle(c,cx,40,13,'#2d4263');circle(c,cx,40,7,'#97c9ed');line(c,cx,31,cx,49,'#131d30',2);
 const weightX=cx+cw/2+32;line(c,weightX,40,weightX,bottom-(12.5-sim.y)*scale-31,'#3b4b69');rect(c,weightX-6,bottom-(12.5-sim.y)*scale-31,12,31,'#384c6b');
 c.save();const jiggle=matchMedia('(prefers-reduced-motion: reduce)').matches?0:shake;c.translate(Math.sin(sim.t*90)*jiggle,0);rect(c,x-5,y-7,cw+10,ch+14,'#607b9d');rect(c,x,y,cw,ch,'#202c42');const grad=c.createLinearGradient(x,y,x+cw,y+ch);grad.addColorStop(0,'#304866');grad.addColorStop(1,'#152136');rect(c,x+3,y+3,cw-6,ch-6,grad);line(c,cx,y+4,cx,y+ch-4,'#4b5c79');line(c,x+7,y+ch*.55,x+cw-7,y+ch*.55,'#7b94b3',2);rect(c,x+cw*.28,y+4,cw*.44,2,colors.lime);rect(c,x-5,y+ch+5,cw+10,5,'#a4cef0');for(let i=0;i<cw;i+=14){line(c,x+i,y+ch+6,x+i+6,y+ch+10,'#22354e',3);}
 c.save();c.beginPath();c.rect(x+2,y+2,cw-4,ch-4);c.clip();
 // Persistent cabin splashes and gravity streaks.
 for(const s of stains){circle(c,x+4+s.x*(cw-8),y+3+s.y*(ch-6),s.r,'#912d36');line(c,x+4+s.x*(cw-8),y+3+s.y*(ch-6),x+4+s.x*(cw-8),y+3+s.y*(ch-6)+s.drip,'#70272f',Math.max(1,s.r*.4));}
 const humanH=ch*.66,humanScale=humanH/51;
 for(let i=0;i<sim.count;i++){const q=sim.people[i],px=x+cw*(.16+.68*(i+.5)/sim.count),foot=y+ch-4-q.z*scale,sway=clamp(sim.a*.35,-5,5)+Math.sin(sim.t*3+i)*Math.min(Math.abs(sim.v),1.5),squat=clamp(sim.a*.13,0,4);c.save();c.translate(px,foot);c.scale(humanScale,humanScale);const coat=['#7dccff','#d7829e','#e0ecff','#a5bafa','#bcc7d8','#e598a4'][i];c.lineCap='round';c.lineJoin='round';const hip=-21+squat,neck=-38+squat;line(c,sway*.5,hip,-7,0,'#b2c0b3',4);line(c,sway*.5,hip,7,0,'#b2c0b3',4);line(c,sway,neck,sway*.5,hip,coat,8);const arm=q.z>.02?-34:-20;line(c,sway,neck+3,-10+sway,arm,coat,3);line(c,sway,neck+3,10+sway,arm,coat,3);circle(c,sway,neck-8,6,'#d7c9ab');circle(c,sway-2,neck-9,.8,'#263129');circle(c,sway+2,neck-9,.8,'#263129');if(sim.health<40)circle(c,sway,neck-5,1.8,'#573132');else line(c,sway-2,neck-5,sway+2,neck-5,'#485443');c.restore();}
 for(const p of particles){c.globalAlpha=Math.min(1,p.life*2);const xx=x+p.x*cw,yy=y+p.y*ch;line(c,xx,yy,xx-p.vx*3,yy-p.vy*3,'#e15060',p.r);circle(c,xx,yy,p.r,'#d83b4e');}c.globalAlpha=1;c.restore();c.restore();
 text(c,'800 kg CABIN',cx-cw/2,y-15,'#a1b0c6',9);if(sim.count===0)text(c,'EMPTY',cx-17,y+ch*.55,'#8b9ab2',10);
}
function drawGraph(){const{ctx:c,w,h}=canvas('graph');c.clearRect(0,0,w,h);const left=36,right=w-12,top=13,bottom=h-24;const isPos=view==='position';let lo=isPos?0:-24,hi=isPos?15:24;if(!isPos)for(const a of sim.history)for(const k of['p','i','d']){lo=Math.min(lo,a[k]/1000);hi=Math.max(hi,a[k]/1000);}const yy=v=>bottom-(v-lo)/(hi-lo)*(bottom-top);for(let i=0;i<=3;i++){const v=lo+(hi-lo)*i/3;line(c,left,yy(v),right,yy(v),'#2a3430');text(c,Math.round(v)+(isPos?'m':''),1,yy(v)+4,'#7f8c86',10);}const start=Math.max(0,sim.t-20);for(let i=0;i<=4;i++){const x=left+(right-left)*i/4;line(c,x,top,x,bottom,'#232c28');text(c,(start+i*5).toFixed(0)+'s',x-5,h-5,'#7f8c86',10);}const series=isPos?[['target','#7f8e82'],['y',colors.lime]]:[['p',colors.lime],['i',colors.purple],['d',colors.cyan]];c.save();c.beginPath();c.rect(left,top,right-left,bottom-top);c.clip();if(sim.history.length===0){c.setLineDash([5,5]);line(c,left,yy(isPos?sim.target:0),right,yy(isPos?sim.target:0),'#7f8e82');c.setLineDash([]);if(isPos)line(c,left,yy(0),right,yy(0),colors.lime,2);}for(const[key,color]of series){c.beginPath();c.strokeStyle=color;c.lineWidth=key==='target'?1.4:2;c.setLineDash(key==='target'?[5,5]:[]);sim.history.forEach((a,i)=>{const x=left+(a.t-start)/20*(right-left),y=yy(isPos?a[key]:a[key]/1000);if(i===0)c.moveTo(x,y);else c.lineTo(x,y);});c.stroke();}c.setLineDash([]);c.restore();}
function updateUI(){ $('integral-live').textContent='Accumulated: '+sim.integral.toFixed(2)+' m·s'; $('integral-resets').textContent=sim.integralResets+' reset'+(sim.integralResets===1?'':'s'); $('clock').textContent=sim.t.toFixed(2).padStart(5,'0')+' s';$('position').innerHTML=sim.y.toFixed(2)+' <small>m</small>';$('velocity').innerHTML=sim.v.toFixed(2)+' <small>m/s</small>';$('error').innerHTML=(sim.target-sim.y).toFixed(2)+' <small>m</small>';$('health').innerHTML=Math.round(sim.health)+'<small>%</small>';$('health').style.color=sim.health>70?colors.lime:sim.health>30?'#e5b170':'#f07176';$('overshoot').innerHTML=sim.overshoot.toFixed(1)+' <small>%</small>';$('settling').innerHTML=(sim.settle===null?'—':sim.settle.toFixed(1))+' <small>s</small>';$('peak').innerHTML=sim.peak.toFixed(2)+' <small>g</small>';
 if(mode==='sandbox'){$('insight').textContent=sim.health<40?'That was brutal. Reset and add more D, or reduce P, to soften the ride.':sim.saturated?'Motor limit reached. More gain cannot create more force. Reduce P or I to avoid a rough ride.':sim.settle!==null?'Nice landing. Now add passengers and see if your tuning still holds up.':sim.t>8&&sim.ki===0&&Math.abs(sim.v)<.2&&Math.abs(sim.target-sim.y)>.1?'The load is balanced. Increase P for a faster approach, or reduce excessive D.':sim.overshoot>8?'You overshot the floor. Increase D to brake earlier, or reduce P.':'Watch the response line. P pulls toward the target; D opposes motion; I accumulates error.';}
 else if(!won){const settled=sim.settle!==null,good=sim.health>=80&&(level===1||sim.overshoot<8)&&(level!==2||sim.settle===null||sim.settle<=25);$('challenge-steps').textContent=`${settled?'●':'○'} Reach target   ${good?'●':'○'} Smooth ride`;if(settled&&good){won=true;$('challenge-steps').textContent='✓ CHALLENGE COMPLETE';$('insight').textContent=level===2?'All three passed. You balanced speed, integral memory, and damping. Take those gains into the sandbox.':'Good tuning. The cabin is settled and the ride meets the goal.';$('next-lesson').hidden=false;$('next-lesson').textContent=level===2?'Return to sandbox →':'Next challenge →';running=false;status();}else if(sim.health<80||level!==1&&sim.overshoot>=8||level===2&&sim.t>25){$('insight').textContent='This ride missed a goal. Adjust your gains and Reset to try again. Reduce P or I for less overshoot; add D for more damping.';}}
 if(running)$('run-status').textContent=sim.health<=0?'ROUGH RIDE':sim.settle!==null?'● SETTLED':sim.saturated?'MOTOR LIMIT':'● RUNNING';}
function frame(t){const dt=last?Math.min((t-last)/1000,.05):0;last=t;if(running&&!document.hidden){accumulator+=dt*Number($('speed').value);while(accumulator>=.005){sim.step(.005);if(sim.impact>2.5)emit(sim.impact);animateBlood(.005);accumulator-=.005;}}drawShaft();drawGraph();if(++drawTick%5===0)updateUI();requestAnimationFrame(frame);}
document.addEventListener('visibilitychange',()=>{last=0;accumulator=0;});updateFloor();updateLoad();updateUI();status();requestAnimationFrame(frame);
